local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local B64I = {}
for i = 1, #B64 do B64I[B64:sub(i, i)] = i - 1 end
local function b64decode(s)
	local out = buffer.create(math.floor(#s * 3 / 4) + 3)
	local n = 0
	local bits = 0
	local acc = 0
	for i = 1, #s do
		local c = s:sub(i, i)
		if c == "=" then break end
		local v = B64I[c]
		if v then
			acc = acc * 64 + v
			bits = bits + 6
			if bits >= 8 then
				bits = bits - 8
				buffer.writeu8(out, n, math.floor(acc / (2 ^ bits)) % 256)
				n = n + 1
			end
		end
	end
	return buffer.readstring(out, 0, n)
end
local raw = b64decode(PAYLOAD)
local rawBuf = buffer.fromstring(raw)
local state = KEY % 4294967296
local decBuf = buffer.create(#raw)
for i = 1, #raw do
	state = (1664525 * state + 1013904223) % 4294967296
	buffer.writeu8(decBuf, i - 1, bit32.bxor(buffer.readu8(rawBuf, i - 1), state % 256))
end
local code = buffer.tostring(decBuf)
local fn, err = loadstring(code)
if not fn then
	warn("[LUNAR Library] decode failed: " .. tostring(err))
	return
end
return fn()
